    if (typeof fieldName !== 'string') return { field: null, index: null }
    const match = /^([A-Za-z]+)(?:\[(\d+)\])?/u.exec(fieldName)
    if (!match) return { field: null, index: null }

    return { field: match[1], index: match[2] === undefined ? null : Number(match[2]) }
